namespace sv_4ba56998b4014ee5ad0bfb808df9e145.Services;

public enum Theme
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service that holds per-circuit theme state.
/// In Blazor Server, "scoped" means one instance per circuit (per user tab),
/// so each user gets independent theme state.
/// </summary>
public class ThemeService
{
    public Theme CurrentTheme { get; private set; } = Theme.System;
    public string AccentColor { get; private set; } = "#0d6efd";

    public event Action? OnChanged;

    public void SetTheme(Theme theme)
    {
        if (CurrentTheme == theme) return;
        CurrentTheme = theme;
        OnChanged?.Invoke();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        OnChanged?.Invoke();
    }

    public void ApplyPreferences(Theme theme, string accentColor)
    {
        var changed = CurrentTheme != theme || AccentColor != accentColor;
        CurrentTheme = theme;
        AccentColor = accentColor;
        if (changed) OnChanged?.Invoke();
    }
}

@* This component is rendered with @rendermode InteractiveServer inside the
   static MainLayout so it can subscribe to ThemeService change events. *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="badge rounded-pill"
      style="background-color: @ThemeService.AccentColor; color: white;">
    @ThemeService.CurrentTheme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleThemeChanged;
    }

    private void HandleThemeChanged()
    {
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleThemeChanged;
    }
}

@* Quick toggle rendered interactively inside the sidebar. *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<div class="nav-item px-3 py-2">
    <label class="form-label text-light mb-1" style="font-size: 0.85rem;">Theme</label>
    <select class="form-select form-select-sm"
            value="@ThemeService.CurrentTheme"
            @onchange="OnThemeSelected">
        @foreach (var t in Enum.GetValues<Theme>())
        {
            <option value="@t">@t</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChanged += HandleChanged;
    }

    private void OnThemeSelected(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var theme))
        {
            ThemeService.SetTheme(theme);
        }
    }

    private void HandleChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select"
                    value="@selectedTheme"
                    @onchange="OnThemeChanged">
                @foreach (var t in Enum.GetValues<Theme>())
                {
                    <option value="@t">@t</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <input type="color" class="form-control form-control-color"
                   value="@accentColor"
                   @onchange="OnColorChanged" />
            <small class="text-muted">@accentColor</small>
        </div>

        <button class="btn btn-primary" @onclick="Save"
                style="background-color: @accentColor; border-color: @accentColor;">
            Save Preferences
        </button>

        @if (saved)
        {
            <span class="text-success ms-2">✓ Saved</span>
        }
    </div>
</div>

<div class="mt-4">
    <h5>Live Preview</h5>
    <p>Current theme: <strong>@ThemeService.CurrentTheme</strong></p>
    <p>Current accent:
        <span class="badge" style="background-color: @ThemeService.AccentColor; color: white;">
            @ThemeService.AccentColor
        </span>
    </p>
</div>

@code {
    private Theme selectedTheme;
    private string accentColor = "#0d6efd";
    private bool saved;

    protected override void OnInitialized()
    {
        selectedTheme = ThemeService.CurrentTheme;
        accentColor = ThemeService.AccentColor;
        ThemeService.OnChanged += HandleChanged;
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var theme))
            selectedTheme = theme;
    }

    private void OnColorChanged(ChangeEventArgs e)
    {
        accentColor = e.Value?.ToString() ?? accentColor;
    }

    private void Save()
    {
        ThemeService.ApplyPreferences(selectedTheme, accentColor);
        saved = true;
    }

    private void HandleChanged()
    {
        selectedTheme = ThemeService.CurrentTheme;
        accentColor = ThemeService.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleChanged;
    }
}

