@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 480px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select"
                    value="@selectedTheme"
                    @onchange="OnThemeChanged">
                @foreach (var t in Enum.GetValues<Theme>())
                {
                    <option value="@t">@t</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <input type="color" class="form-control form-control-color"
                   value="@accentColor"
                   @onchange="OnColorChanged" />
            <small class="text-muted">@accentColor</small>
        </div>

        <button class="btn btn-primary" @onclick="Save"
                style="background-color: @accentColor; border-color: @accentColor;">
            Save Preferences
        </button>

        @if (saved)
        {
            <span class="text-success ms-2">✓ Saved</span>
        }
    </div>
</div>

<div class="mt-4">
    <h5>Live Preview</h5>
    <p>Current theme: <strong>@ThemeService.CurrentTheme</strong></p>
    <p>Current accent:
        <span class="badge" style="background-color: @ThemeService.AccentColor; color: white;">
            @ThemeService.AccentColor
        </span>
    </p>
</div>

@code {
    private Theme selectedTheme;
    private string accentColor = "#0d6efd";
    private bool saved;

    protected override void OnInitialized()
    {
        selectedTheme = ThemeService.CurrentTheme;
        accentColor = ThemeService.AccentColor;
        ThemeService.OnChanged += HandleChanged;
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var theme))
            selectedTheme = theme;
    }

    private void OnColorChanged(ChangeEventArgs e)
    {
        accentColor = e.Value?.ToString() ?? accentColor;
    }

    private void Save()
    {
        ThemeService.ApplyPreferences(selectedTheme, accentColor);
        saved = true;
    }

    private void HandleChanged()
    {
        selectedTheme = ThemeService.CurrentTheme;
        accentColor = ThemeService.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChanged -= HandleChanged;
    }
}

